/* ── 静态状态 ── */
static lv_obj_t *s_pet_screen = NULL;
static lv_obj_t *s_canvas      = NULL;
/* ARGB8888 canvas: 192*192*4 = 147456 字节。放 PSRAM 避免吃内部 RAM。*/
static lv_color32_t *s_canvas_buf = NULL;
static pet_state_t s_cur_state = PET_STATE_HAPPY;
static void (*s_back_cb)(void) = NULL;

/* ── 把 1bpp 字模画到 canvas ──
 * 用 ARGB8888 canvas（每像素 4 字节），避开 LVGL v9 I1 索引色 canvas 的
 * stride/对齐坑。逐像素直接写 0xFFFFFFFF(白) / 0xFF000000(黑)。
 * 透明背景按白处理。*/
static void draw_bitmap(const uint8_t *bmp)
{
    lv_canvas_fill_bg(s_canvas, lv_color_white(), LV_OPA_COVER);
    lv_color32_t *px = (lv_color32_t *)s_canvas_buf;
    for (int y = 0; y < PET_H; y++) {
        for (int x = 0; x < PET_W; x++) {
            uint8_t byte = bmp[y * PET_ROW_BYTES + (x >> 3)];
            uint8_t bit  = 0x80 >> (x & 7);
            if (byte & bit) {
                lv_color32_t c = lv_color32_make(0, 0, 0, 255);       /* 黑 */
                px[y * PET_W + x] = c;
            } else {
                lv_color32_t c = lv_color32_make(255, 255, 255, 255); /* 白 */
                px[y * PET_W + x] = c;
            }
        }
    }
    lv_obj_invalidate(s_canvas);
}

static void apply_state(pet_state_t s)
{
    if (s >= PET_STATE_COUNT) s = PET_STATE_HAPPY;
    s_cur_state = s;
    draw_bitmap(s_pet_bitmap[s]);
}

/* ── 点触交互：单击 → dashboard，长按 → TODO ── */
static void screen_clicked_cb(lv_event_t *e)
{
    (void)e;
    if (s_back_cb) s_back_cb();   /* main.cpp 设为 ui_switch_page(PAGE_DASHBOARD) */
}

static void screen_longpress_cb(lv_event_t *e)
{
    (void)e;
    /* 长按 → 跳 TODO 列表页 */
    ui_switch_page(PET_PAGE_TODO_LISTS);
}

/* ── 聚合设备状态算表情 ── */
static pet_state_t compute_state(void)
{
    /* 1. 夜间优先 */
    rtc_datetime_t t = PortRtc_GetTime();
    if (t.hour >= 22 || t.hour < 6) {
        return PET_STATE_SLEEP;
    }

    /* 2. 低电量 */
    uint8_t batt = PortBattery_GetLevel();
    if (batt < 20) {
        return PET_STATE_LOW_BATT;
    }

    /* 3. 计时器运行中（番茄钟或提醒）*/
    timer_instance_t slots[TIMER_MAX_SLOTS];
    uint8_t slot_cnt = 0;
    if (TimerEngine_GetAll(slots, &slot_cnt) == ESP_OK) {
        for (uint8_t i = 0; i < slot_cnt; i++) {
            if (slots[i].active) {
                return PET_STATE_FOCUS;
            }
        }
    }

    /* 4. TODO 数量 */
    static todo_list_t lists[TODO_MAX_LISTS];
    static todo_task_t tasks[TODO_MAX_TASKS];
    uint8_t list_cnt = 0;
    if (TodoMgr_GetLists(lists, &list_cnt) == ESP_OK) {
        int undone = 0;
        for (uint8_t i = 0; i < list_cnt; i++) {
            uint16_t tcnt = 0;
            if (TodoMgr_GetTasks(lists[i].id, tasks, &tcnt) != ESP_OK) continue;
            for (uint16_t j = 0; j < tcnt; j++) {
                if (!tasks[j].done) undone++;
            }
        }
        if (undone >= 5) return PET_STATE_ANXIOUS;
        if (undone >= 1) return PET_STATE_BUSY;
    }

    return PET_STATE_HAPPY;
}

/* ──────────────────────────────────────────────────────────────
 * 公开 API
 * ────────────────────────────────────────────────────────────── */

esp_err_t PetUi_Init(void)
{
    if (s_pet_screen) return ESP_OK;

    s_pet_screen = lv_obj_create(NULL);
    lv_obj_set_size(s_pet_screen, 200, 200);
    lv_obj_set_scrollbar_mode(s_pet_screen, LV_SCROLLBAR_MODE_OFF);
    lv_obj_set_style_bg_color(s_pet_screen, lv_color_white(), 0);
    lv_obj_set_style_bg_opa(s_pet_screen, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(s_pet_screen, 0, 0);
    lv_obj_set_style_radius(s_pet_screen, 0, 0);
    lv_obj_set_style_pad_all(s_pet_screen, 0, 0);
    lv_obj_add_flag(s_pet_screen, LV_OBJ_FLAG_CLICKABLE);

    /* 像素角色 canvas：ARGB8888，避开 I1 索引色对齐坑 */
    s_canvas_buf = (lv_color32_t *)heap_caps_malloc(PET_W * PET_H * sizeof(lv_color32_t),
                                                    MALLOC_CAP_SPIRAM);
    if (s_canvas_buf == NULL) {
        ESP_LOGE(TAG, "canvas buf alloc failed");
        return ESP_ERR_NO_MEM;
    }
    s_canvas = lv_canvas_create(s_pet_screen);
    lv_canvas_set_buffer(s_canvas, s_canvas_buf, PET_W, PET_H, LV_COLOR_FORMAT_ARGB8888);
    lv_obj_set_pos(s_canvas, PET_CX, PET_CY);

    /* 交互：点触返回 dashboard，长按看 TODO（无文字提示，靠操作探索）*/
    lv_obj_add_event_cb(s_pet_screen, screen_clicked_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_event_cb(s_pet_screen, screen_longpress_cb, LV_EVENT_LONG_PRESSED, NULL);

    apply_state(PET_STATE_HAPPY);
    ESP_LOGI(TAG, "pet_ui init done");
    return ESP_OK;
}

lv_obj_t *PetUi_GetScreen(void)
{
    return s_pet_screen;
}

void PetUi_SetState(pet_state_t s)
{
    if (!s_pet_screen) return;
    apply_state(s);
}

void PetUi_Refresh(void)
{
    if (!s_pet_screen) return;
    pet_state_t s = compute_state();
    if (s != s_cur_state) {
        apply_state(s);
    }
}

void PetUi_SetBackCallback(void (*cb)(void))
{
    s_back_cb = cb;
}
